function utf8Encode(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.codePointAt(i);
    if (code > 0xFFFF) i++;
    if (code < 0x80) bytes.push(code);
    else if (code < 0x800) bytes.push(0xC0 | (code >> 6), 0x80 | (code & 0x3F));
    else if (code < 0x10000) bytes.push(0xE0 | (code >> 12), 0x80 | ((code >> 6) & 0x3F), 0x80 | (code & 0x3F));
    else bytes.push(0xF0 | (code >> 18), 0x80 | ((code >> 12) & 0x3F), 0x80 | ((code >> 6) & 0x3F), 0x80 | (code & 0x3F));
  }
  return bytes;
}

function deflateStored(bytes) {
  const out = [];
  const max = 65535;
  if (bytes.length === 0) { out.push(0x01, 0x00, 0x00, 0xFF, 0xFF); return out; }
  let i = 0;
  while (i < bytes.length) {
    const chunk = bytes.slice(i, i + max);
    const isLast = i + max >= bytes.length;
    out.push(isLast ? 0x01 : 0x00);
    const len = chunk.length;
    const nlen = (~len) & 0xFFFF;
    out.push(len & 0xFF, (len >> 8) & 0xFF, nlen & 0xFF, (nlen >> 8) & 0xFF);
    for (let j = 0; j < chunk.length; j++) out.push(chunk[j]);
    i += max;
  }
  return out;
}

function encode6bit(c) {
  if (c < 0) c += 64;
  if (c < 26) return String.fromCharCode(65 + c);
  if (c < 52) return String.fromCharCode(97 + (c - 26));
  if (c < 62) return String.fromCharCode(48 + (c - 52));
  if (c === 62) return '-';
  return '_';
}

function plantUmlEncode(text) {
  const deflated = deflateStored(utf8Encode(text));
  let result = '';
  for (let i = 0; i < deflated.length; i += 3) {
    const b1 = deflated[i];
    const b2 = i + 1 < deflated.length ? deflated[i + 1] : 0;
    const b3 = i + 2 < deflated.length ? deflated[i + 2] : 0;
    result += encode6bit(b1 >> 2);
    result += encode6bit(((b1 & 0x3) << 4) | (b2 >> 4));
    result += encode6bit(((b2 & 0xF) << 2) | (b3 >> 6));
    result += encode6bit(b3 & 0x3F);
  }
  return result;
}

const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;

const exported = await tools.structurizr["export-c4plantuml"]({ dsl, viewKey: "SystemContext" });
const puml = exported.definition;
const encoded = plantUmlEncode(puml);
return { puml, encoded, url: "https://www.plantuml.com/plantuml/png/" + encoded };

